                    for j in range(len(rem) + 1):
                        if j == i:
                            continue
                        cand = rem[:j] + [node] + rem[j:]
                        if route_cost(cand) + 1e-12 < base:
                            routes[r] = cand
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break
            if improved:
                continue
            # inter-route relocate
            for a in range(len(routes)):
                for b in range(len(routes)):
                    if a == b:
                        continue
                    ra = routes[a]
                    rb = routes[b]
                    if not ra:
                        continue
                    ca = route_cost(ra) + route_cost(rb)
                    for i in range(len(ra)):
                        node = ra[i]
                        ra2 = ra[:i] + ra[i + 1:]
                        if route_load(ra2) > capacity:
                            continue
                        for j in range(len(rb) + 1):
                            rb2 = rb[:j] + [node] + rb[j:]
                            if route_load(rb2) <= capacity:
                                cb = route_cost(ra2) + route_cost(rb2)
                                if cb + 1e-12 < ca:
                                    routes[a] = ra2
                                    routes[b] = rb2
                                    improved = True
                                    break
                        if improved:
                            break
                    if improved:
                        break
                if improved:
                    break
        return routes

    # --------- parse instance ---------
    depot = get_depot(instance)
    capacity = get_capacity(instance)
    if capacity is None:
        capacity = 10 ** 18
    demands = get_demands(instance)
    coords = get_coords(instance)
    dm = get_distance_matrix(instance)
    customers = all_customers(instance, depot)

    if not customers:
        return []

    # --------- constructive phase ---------
    remaining = customers[:]
    routes = []

    # If coordinates exist, use deterministic angular sweep around depot.
    if coords is not None and depot in coords:
        try:
            dx0, dy0 = coords[depot]
            def angle_key(n):
                x, y = coords[n]
                # Quadrant-like deterministic ordering without imports
                dx = x - dx0
                dy = y - dy0
                if dx == 0 and dy == 0:
                    return (0, 0, n)
                upper = 0 if dy > 0 or (dy == 0 and dx >= 0) else 1
                # approximate slope order within half-plane
                if dx == 0:
                    slope = 10 ** 18 if dy > 0 else -10 ** 18
                else:
                    slope = dy / dx
                return (upper, slope, dist(depot, n), n)
            remaining.sort(key=angle_key)
        except Exception:
            remaining.sort(key=lambda n: (dist(depot, n), n))
    else:
        remaining.sort(key=lambda n: (demand_of(n), dist(depot, n), n))

    # Seed routes by farthest/most demanding first if no coords.
    unserved = remaining[:]

    while unserved:
        route = []
        load = 0
        # pick a seed deterministically
        seed_idx = 0
        best_score = None
        for i, n in enumerate(unserved):
            score = (dist(depot, n), demand_of(n), n)
            if best_score is None or score > best_score:
                best_score = score
                seed_idx = i
        seed = unserved.pop(seed_idx)
        route.append(seed)
        load += demand_of(seed)

        # greedy add by cheapest insertion among feasible unserved
        while True:
            best_node = None
            best_pos = None
            best_delta = None
            for n in unserved:
                dn = demand_of(n)
                if load + dn > capacity:
                    continue
                pos, dlt = best_insertion_position(route, n)
                score = (dlt, dist(route[-1], n), dn, n)
                if best_node is None or score < best_score2:
                    best_node = n
                    best_pos = pos
                    best_delta = dlt
                    best_score2 = score
            if best_node is None:
                break
            route = route[:best_pos] + [best_node] + route[best_pos:]
            load += demand_of(best_node)
            unserved.remove(best_node)

        routes.append(route)

    # --------- repair: split any infeasible route if needed ---------
    repaired = []
    for route in routes:
        cur = []
        cur_load = 0
        for n in route:
            dn = demand_of(n)
            if cur and cur_load + dn > capacity:
                repaired.append(cur)
                cur = [n]
                cur_load = dn
            else:
                cur.append(n)
                cur_load += dn
        if cur:
            repaired.append(cur)
    routes = repaired

    # --------- local improvement ---------
    for i in range(len(routes)):
        routes[i] = two_opt(routes[i])

    routes = relocate_improve(routes)

    # Final deterministic cleanup: ensure all customers exactly once.
    seen = {}
    for r in routes:
        for n in r:
            seen[n] = seen.get(n, 0) + 1

    # Remove duplicates by keeping first occurrence, then reinsert missing.
    if any(v != 1 for v in seen.values()) or len(seen) != len(customers):
        flat = []
        used = {}
        for r in routes:
            nr = []
            for n in r:
                if n not in used:
                    used[n] = True
                    nr.append(n)
            if nr:
                flat.append(nr)
        missing = [n for n in customers if n not in used]
        for n in missing:
            best_r = None
            best_pos = None
            best_inc = None
            for ri, r in enumerate(flat):
                if route_load(r) + demand_of(n) <= capacity:
                    pos, inc = best_insertion_position(r, n)
                    if best_inc is None or inc < best_inc or (inc == best_inc and ri < best_r):
                        best_r = ri
                        best_pos = pos
                        best_inc = inc
            if best_r is None:
                flat.append([n])
            else:
                flat[best_r] = flat[best_r][:best_pos] + [n] + flat[best_r][best_pos:]
        routes = flat

    # Ensure capacity.
    final_routes = []
    for r in routes:
        cur = []
        cur_load = 0
        for n in r:
            dn = demand_of(n)
            if cur and cur_load + dn > capacity:
                final_routes.append(cur)
                cur = [n]
                cur_load = dn
            else:
                cur.append(n)
                cur_load += dn
        if cur:
            final_routes.append(cur)

    # Last pass: remove empty routes and sort routes deterministically by first node then cost.
    final_routes = [r for r in final_routes if r]
    final_routes.sort(key=lambda r: (r[0], route_cost(r), len(r)))

    return final_routes
